const L = params.length;
const W = L * 0.245;
const H = L * 0.285;
const baseY = H * 0.12;
const wheelR = H * 0.115;
const wheelW = W * 0.075;
const sideZ = W * 0.5 + wheelW * 0.18;
const bodyMat = { preset: 'metal', color: params.color, metalness: 0.18, roughness: 0.38 };
const dark = { preset: 'metal', color: '#20252b', metalness: 0.45, roughness: 0.32 };
const glass = { preset: 'glass', color: '#263e4e', roughness: 0.12, metalness: 0.12, opacity: 0.88 };
const rubber = { preset: 'rubber', color: '#17191b', roughness: 0.92 };
const hub = { preset: 'metal', color: '#aeb5ba', metalness: 0.82, roughness: 0.26 };
const light = { preset: 'emissive', color: '#fff2c2', emissive: '#fff0a0', emissiveIntensity: 2.5 };
const redLight = { preset: 'emissive', color: '#d72828', emissive: '#ff2222', emissiveIntensity: 1.8 };
const amber = { preset: 'emissive', color: '#ffb11f', emissive: '#ff9c12', emissiveIntensity: 2.8 };
api.add(api.box(L * 0.94, H * 0.48, W).translate(0, baseY + H * 0.25, 0), bodyMat);
api.add(api.box(L * 0.91, H * 0.43, W * 0.97).translate(0, baseY + H * 0.68, 0), bodyMat);
api.add(api.box(L * 0.88, H * 0.065, W * 0.9).translate(0, baseY + H * 0.925, 0), bodyMat);
api.add(api.cylinder(W * 0.43, W * 0.43, L * 0.82, 16).rotate(0, 0, 90).scale(1, 0.22, 1).translate(0, baseY + H * 0.94, 0), bodyMat);
api.add(api.box(L * 0.98, H * 0.055, W * 1.035).translate(0, baseY + H * 0.08, 0), dark);
api.add(api.box(L * 0.95, H * 0.045, W * 1.025).translate(0, baseY + H * 0.43, 0), dark);
const winY = baseY + H * 0.695;
const winH = H * 0.31;
const panelCount = 7;
const usable = L * 0.72;
const panelW = usable / panelCount * 0.88;
for (let side = -1; side <= 1; side += 2) {
  for (let i = 0; i < panelCount; i++) {
    const x = -usable * 0.5 + (i + 0.5) * usable / panelCount;
    const isDoor = side > 0 && (i === 1 || i === 2);
    if (!isDoor) api.add(api.box(panelW, winH, H * 0.012).translate(x, winY, side * (W * 0.493)), glass);
  }
}
const doorX = -L * 0.255;
api.add(api.box(L * 0.205, H * 0.58, H * 0.018).translate(doorX, baseY + H * 0.43, W * 0.505), glass);
api.add(api.box(H * 0.025, H * 0.59, H * 0.024).translate(doorX, baseY + H * 0.43, W * 0.516), dark);
api.add(api.box(L * 0.215, H * 0.025, H * 0.024).translate(doorX, baseY + H * 0.135, W * 0.516), dark);
api.add(api.box(L * 0.205, H * 0.025, H * 0.024).translate(doorX, baseY + H * 0.72, W * 0.516), dark);
api.add(api.box(H * 0.018, H * 0.14, H * 0.025).translate(doorX + L * 0.02, baseY + H * 0.41, W * 0.527), hub);
api.add(api.box(H * 0.018, H * 0.14, H * 0.025).translate(doorX - L * 0.02, baseY + H * 0.41, W * 0.527), hub);
api.add(api.box(H * 0.018, winH * 0.88, W * 0.68).translate(-L * 0.458, winY, 0), glass);
api.add(api.box(H * 0.018, winH * 0.72, W * 0.72).translate(L * 0.458, winY, 0), glass);
const axleX = [-L * 0.31, L * 0.18, L * 0.32];
for (let a = 0; a < axleX.length; a++) {
  for (let side = -1; side <= 1; side += 2) {
    api.add(api.cylinder(wheelR, wheelR, wheelW, 14).rotate(90, 0, 0).translate(axleX[a], wheelR, side * sideZ), rubber);
    api.add(api.cylinder(wheelR * 0.48, wheelR * 0.48, wheelW * 1.08, 12).rotate(90, 0, 0).translate(axleX[a], wheelR, side * (sideZ + side * wheelW * 0.03)), hub);
  }
}
api.add(api.box(L * 0.28, H * 0.105, H * 0.018).translate(-L * 0.467, baseY + H * 0.845, 0), dark);
api.add(api.box(H * 0.02, H * 0.058, W * 0.48).translate(-L * 0.478, baseY + H * 0.845, 0), amber);
api.add(api.box(L * 0.18, H * 0.085, H * 0.018).translate(L * 0.467, baseY + H * 0.83, 0), dark);
api.add(api.box(H * 0.02, H * 0.04, W * 0.31).translate(L * 0.478, baseY + H * 0.83, 0), amber);
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(H * 0.024, H * 0.075, W * 0.18).translate(-L * 0.482, baseY + H * 0.265, side * W * 0.3), light);
  api.add(api.box(H * 0.024, H * 0.075, W * 0.16).translate(L * 0.482, baseY + H * 0.28, side * W * 0.31), redLight);
  api.add(api.box(L * 0.075, H * 0.055, H * 0.03).translate(-L * 0.39, baseY + H * 0.73, side * W * 0.54), dark);
}
api.add(api.box(H * 0.055, H * 0.08, W * 1.06).translate(-L * 0.49, baseY + H * 0.13, 0), dark);
api.add(api.box(H * 0.055, H * 0.08, W * 1.06).translate(L * 0.49, baseY + H * 0.13, 0), dark);
api.collider({ kind: 'box', halfExtents: [L * 0.47, H * 0.44, W * 0.5], offset: [0, baseY + H * 0.48, 0] });
for (let i = 0; i < axleX.length; i++) api.collider({ kind: 'box', halfExtents: [wheelR, wheelR, W * 0.58], offset: [axleX[i], wheelR, 0] });
return api.build();
